#!/usr/bin/env python3
"""Hash-checked UI release. Reads completed evidence; never dispatches a model call."""
import argparse
import base64
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import sys
import urllib.request
import zlib

DATA = json.loads(zlib.decompress(base64.b64decode('')))

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--deploy',action='store_true',help='Deploy the reviewed UI; no model calls or comparison replay')
    args=parser.parse_args(); root=Path.cwd(); private=root/'.jt'
    if not (private/'state.json').is_file():sys.exit('Judgment_Transfer_Runbook_v1.0 フォルダーで実行してください。')
    sys.dont_write_bytecode=True;sys.path.insert(0,str(root));sha=lambda b:hashlib.sha256(b).hexdigest()
    with (private/'runbook.lock').open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:sys.exit('STOP RUNBOOK_BUSY / 別の処理が実行中です。')
        state=json.loads((private/'state.json').read_text())
        if any(state['steps'].get(f'{n:02}',{}).get('status')!='DONE' for n in range(9)):
            sys.exit('STOP STATE_MISMATCH / 00〜08完了済み環境を対象とします。')
        current=json.loads((root/'package-manifest.json').read_text())
        if current not in (DATA['baseline'],DATA['new']):sys.exit('STOP PACKAGE_CHANGED / 未確認のマニフェストです。')
        for name,expected in current['files'].items():
            path=root/name
            if not path.is_file() or sha(path.read_bytes()) not in (expected,DATA['new']['files'].get(name)):
                sys.exit('STOP PACKAGE_CHANGED / 未確認の変更: '+name)
        for name in DATA['files']:
            path=root/name
            if name not in current['files'] and name!='package-manifest.json' and path.exists() and sha(path.read_bytes())!=DATA['new']['files'][name]:
                sys.exit('STOP PACKAGE_CHANGED / 新規ファイルが衝突: '+name)
        if shutil.disk_usage(root).free<64*1024*1024:sys.exit('STOP DISK_SPACE / 空き64MiB未満です。既存記録は削除していません。')
        from steps import runbook as r
        if args.deploy:
            c=r.config()
            if c['project_id']!='jt-261013-a79fce':sys.exit('STOP PROJECT_MISMATCH')
            os.environ['CLOUDSDK_BILLING_QUOTA_PROJECT']=c['project_id']
            api=r.API();health=api.call('/health')
            if health.get('mode')!='LIVE' or health.get('code_hash') not in {DATA['baseline']['code_hash'],DATA['new']['code_hash']}:
                sys.exit('STOP DEPLOY_MISMATCH / 現在の版を確認できません。')
            before=api.call('/recovery115');study=before.get('study') or {}
            if (study.get('phase'),study.get('cursor'),study.get('stop'),study.get('code_hash'))!=('COMPLETE',216,None,'b5ffd242d8256902e309bbe816e631da4c932e93c324a85a1a6edc36af6aa8d4'):
                sys.exit('STOP STUDY_INCOMPLETE / 完了した1.0.15の216件が必要です。追加実行はしていません。')
            if before.get('additional_decisions_limit')!=251 or before.get('additional_decisions_used')!=251 or before.get('session_call_limit')!=509 or before.get('session',{}).get('calls')!=509 or before.get('extra_retry_attempts')!={'limit':6,'used':6} or before.get('max_cost_usd')!=20:
                sys.exit('STOP LIMIT_STATE_MISMATCH / 完了時の上限・使用記録と一致しません。')
        backup=private/'upgrades/1.0.17'
        for name in [*DATA['files'],'.jt/state.json','.jt/benchmark.json']:
            path,dest=root/name,backup/name
            if path.is_file() and not dest.exists():dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,dest)
        for name,value in DATA['files'].items():
            path=root/name;path.parent.mkdir(parents=True,exist_ok=True)
            temporary=path.with_name(path.name+'.upgrade-tmp');temporary.write_bytes(base64.b64decode(value));os.replace(temporary,path)
        r.integrity();state=r.state();state['package_version']='1.0.17'
        state.setdefault('upgrades',{}).setdefault('1.0.17',{'from_version':current['version'],'installed_at':r.stamp(),'code_hash':DATA['new']['code_hash'],'deployed':False})
        r.save(r.STATE,state)
        print('1.0.17 適用済み。保存済みの専門家の説明を、元資料との一致を確認して表示します。',flush=True)
        if not args.deploy:print('ローカル適用のみ。モデル呼び出し・比較再実行は0回です。');return
        original_gc=r.gc
        def preserve_gc(*a,**kw):
            if kw.get('action')=='04-deploy':
                kw['action']='04-deploy-1.0.17';revised=[]
                for value in a:
                    if value=='--no-allow-unauthenticated':continue
                    if value=='--invoker-iam-check':value='--no-invoker-iam-check'
                    if value.startswith('--set-env-vars='):
                        value=value.replace('JT_INPUT_USD_PER_MILLION=1.50','JT_INPUT_USD_PER_MILLION=2.70').replace('JT_OUTPUT_USD_PER_MILLION=9.00','JT_OUTPUT_USD_PER_MILLION=16.20')+',JT_REQUEST_TIER=priority'
                    revised.append(value)
                a=tuple(revised)
            return original_gc(*a,**kw)
        r.gc=preserve_gc
        if health.get('code_hash')!=DATA['new']['code_hash']:
            print('公開設定と利用上限を保持してデプロイします。モデルは呼びません。',flush=True)
            r.step04()
        api=r.API();health=api.call('/health')
        if health.get('package_version')!='1.0.17' or health.get('code_hash')!=DATA['new']['code_hash'] or health.get('request_tier')!='priority' or health.get('mode')!='LIVE' or health.get('max_cost_usd')!=20:
            sys.exit('STOP DEPLOY_MISMATCH / デプロイ版を確認してください。モデル呼び出しは0回です。')
        for name,expected in DATA['new']['files'].items():
            if name.startswith('app/web/'):
                route='/' if name=='app/web/index.html' else '/assets/'+name.removeprefix('app/web/')
                req=urllib.request.Request(r.config()['url']+route,headers={'Cache-Control':'no-cache'})
                with urllib.request.urlopen(req,timeout=30) as response:content=response.read()
                if sha(content)!=expected:sys.exit('STOP ASSET_MISMATCH / 公開ファイル不一致: '+name)
        after=api.call('/recovery115')
        if before!=after:sys.exit('STOP SAVED_STATE_CHANGED / 完了記録または利用記録が変化しました。比較は再実行していません。')
        state=r.state();state['upgrades']['1.0.17'].update(deployed=True,deployed_at=r.stamp());r.save(r.STATE,state)
        report={'version':'1.0.17','code_hash':DATA['new']['code_hash'],'served_assets_verified':True,'completed_study_and_budget_unchanged':True,'model_calls':0,'formal_replays':0,'url':r.config()['url']+'/assets/review/index.html'}
        r.save(root/'deliverables/release116/deploy-verification.json',report)
        print('1.0.17 公開完了。216件・承認・予算・呼び出し回数の保持と公開ファイルの一致を確認しました。')
        print('確認URL: '+report['url']);print('モデル呼び出し0回、比較再実行0回。')

if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:sys.exit('中断しました。保存済み記録は残っています。同じコマンドで再開できます。')
    except Exception as error:
        if hasattr(error,'code'):sys.exit('STOP '+error.code+' / '+str(error))
        sys.exit('STOP RELEASE_ERROR / '+type(error).__name__+'。記録を削除せず確認してください。')
